import ProgressBar from 'primevue/progressbar';

export default {
    name: "loader",
    data() {
        return {
            isLoading: false
        }
    },
    components: {
        ProgressBar
    },
    methods: {
        handleLoadingUpdate(value) {
            console.log(value)
            this.isLoading.value = value;
        }
    }
}
